window.PAZZA_IMG={"accovacciato": "data:image/png;base64,", "aterra": "data:image/png;base64,", "calcio": "data:image/png;base64,", "camminata1": "data:image/png;base64,", "camminata2": "data:image/png;base64,", "caricapalla": "data:image/png;base64,", "caricapugno": "data:image/png;base64,", "colpito": "data:image/png;base64,", "colpitobasso": "data:image/png;base64,", "entrata": "data:image/png;base64,", "fischio": "data:image/png;base64,", "guardia": "data:image/png;base64,", "ko": "data:image/png;base64,", "lancio": "data:image/png;base64,", "montante": "data:image/png;base64,", "osso": "data:image/png;base64,", "ovale": "data:image/png;base64,", "ovalone": "data:image/png;base64,", "palla0": "data:image/png;base64,", "palla1": "data:image/png;base64,", "palla2": "data:image/png;base64,", "palla3": "data:image/png;base64,", "parata": "data:image/png;base64,", "polvere": "data:image/png;base64,", "presa": "data:image/png;base64,", "provocazione": "data:image/png;base64,", "pugno": "data:image/png;base64,", "rialzo": "data:image/png;base64,", "ritratto": "data:image/png;base64,", "salto": "data:image/png;base64,", "sconfitta": "data:image/png;base64,", "sgambetto": "data:image/png;base64,", "stordito": "data:image/png;base64,", "super1": "data:image/png;base64,", "tifo": "data:image/png;base64,", "vittoria": "data:image/png;base64,", "vittoria2": "data:image/png;base64,"};window.PAZZA_SCR={"ASFALTATO": "data:image/png;base64,", "BAU": "data:image/png;base64,", "BRUM_BRUM": "data:image/png;base64,", "CAMPANILE": "data:image/png;base64,", "CHEGGIOCATORE": "data:image/png;base64,", "CODDISSE": "data:image/png;base64,", "DROP": "data:image/png;base64,", "STRIKE": "data:image/png;base64,"};window.PAZZA_SRC="\nQUOTES.pazza={intro:[\"Coddisse.\",\"Maestro, guarda e impara.\",\"Pronto per il terzo tempo.\",\"Placco tutto, anche te.\"],win:[\"CHEGGIOCATORE!\",\"Coddisse.\",\"Terzo tempo: offro io.\",\"Meta. Trasformata.\"],lose:[\"Fallo in mischia...\",\"Arbitro, ma dai!\",\"Coddisse... male.\"]};\nCOUPLE.pazza=COUPLE.pazza||{}; COUPLE.pazza.stefano={intro:[\"Maestro! Oggi l'allievo ti placca.\"],win:[\"Scusa, Maestro. CHEGGIOCATORE!\"],lose:[\"Il Maestro \u00e8 sempre il Maestro.\"]};\nCOUPLE.stefano=COUPLE.stefano||{}; COUPLE.stefano.pazza={intro:[\"Pazza Idea. Chiamami ancora Maestro.\"],win:[\"Lezione finita, allievo.\"],lose:[\"L'allievo ha superato il Maestro. Agli atti.\"]};\nCOUPLE.pazza.cugi={intro:[\"Cugi! Prima linea contro prima linea.\"],win:[\"Coddisse. Offri tu la birra.\"],lose:[\"STRAORDINERIO... per te.\"]};\nCOUPLE.cugi=COUPLE.cugi||{}; COUPLE.cugi.pazza={intro:[\"Pazza Idea, ti ho visto giocare. Sorridi alla foto.\"],win:[\"STRAORDINERIO!\"],lose:[\"Placcato da un amico. Fa pi\u00f9 male.\"]};\nCOUPLE.pazza.ciuppa={intro:[\"Ciuppa, dopo questa mischia, birra.\"],win:[\"Terzo tempo: paghi tu.\"],lose:[\"Dolcetto... a me no.\"]};\nCOUPLE.ciuppa=COUPLE.ciuppa||{}; COUPLE.ciuppa.pazza={intro:[\"Pazza Idea! Che pazza idea, sfidarmi.\"],win:[\"MISCHIA! Vinta.\"],lose:[\"Va bene, la birra la offro io.\"]};\nCOUPLE.pazza.ciarli={intro:[\"Ciarli, a rugby non si chiacchiera.\"],win:[\"Coddisse.\"],lose:[\"Oh tzi... CHE GIOCATORE il Ciarli.\"]};\nCOUPLE.ciarli=COUPLE.ciarli||{}; COUPLE.ciarli.pazza={intro:[\"PAZZA IDEA! Ma che idea \u00e8?\"],win:[\"OH TZI! Placcato il placcatore!\"],lose:[\"Ok, ok: CHEGGIOCATORE.\"]};\nif(SPRITES.pazza){ const N=SPRITES.pazza; N.guardia2=N.guardia; N.paratabassa=N.accovacciato; N.lancio2=N.lancio; N.caricacalcio=N.caricapugno; N.sguardo=N.provocazione; N.turbo=N.pugno; N.sfondamento=N.palla0||N.pugno; N.stordita=N.stordito; N.super2=N.super1; N.esulta1=N.vittoria; N.esulta2=N.tifo; N.esulta3=N.vittoria; N.volo=N.ko; N.svenuto0=N.aterra; N.vittoria3=N.vittoria2; }\n/* PAZZA1 - PAZZA IDEA, rugbista. Base: distanza \"Drop\" (ovale calciato, DROP!); speciale \"Palla umana\" (si arrotola e travolge, STRIKE!);\n   montante \"Hand-off\"; super \"Campanile\" (calcia l'ovale altissimo, ricade gigante sull'avversario, CAMPANILE!).\n   Evoluzione col costume del suo cane: distanza \"Osso\" (BAU!); speciale \"Palla umana\" da cane; super \"In moto\" (lo investe in moto, BRUM BRUM!, ASFALTATO!). */\nfunction pazzaImg(n){ const D=window.PAZZA_IMG||{}, c=SPRITES.__pzImg=SPRITES.__pzImg||{}; if(!D[n]) return null; if(!c[n]){ const i=new Image(); i.src=D[n]; c[n]=i; } return c[n].complete&&c[n].width?c[n]:null; }\ntry{ setTimeout(()=>['ovale','ovalone','osso','polvere'].forEach(pazzaImg),0); }catch(e){}\nconst PZSU={dmgCam:17,rngCam:95,dmgM:18,velM:14};\nfunction drawPazzaProj(p){ const im=pazzaImg(p.kind==='osso'?'osso':'ovale'); if(!im) return false; const s=p.kind==='osso'?0.6:0.55; ctx.save(); ctx.translate(p.x,p.y); ctx.rotate((p.x/(p.kind==='osso'?22:18))*(p.vx<0?-1:1)); ctx.imageSmoothingEnabled=false; ctx.drawImage(im,-im.width*s/2,-im.height*s/2,im.width*s,im.height*s); ctx.restore(); return true; }\nfunction callPazza(f,o){ if(f.def.lv>=2&&pazzaMotoOk(f)){ floatText('BRUM BRUM!',f.x,f.y-270,'#ffb347',26,60); floatText('Coddisse!',f.x,f.y-230,f.def.accent,16,46,'balloon'); try{ tone('sawtooth',90,320,.6,.09); }catch(e){} return; }\n  f.pcam={t:0,tgt:o,hx:o?o.x:f.x+(f.facing||1)*240,done:0}; floatText(rnd()<.5?'Coddisse!':'Maestro, guarda in alto!',f.x,f.y-250,f.def.accent,16,50,'balloon'); try{ tone('triangle',330,990,.6,.08); }catch(e){} }\nfunction stepPazza(f,o){ const C=f.pcam; if(!C) return; C.t++; const tg=o||C.tgt;\n  if(tg&&C.t<40) C.hx+=Math.max(-4.5,Math.min(4.5,tg.x-C.hx));\n  if(C.t===58&&!C.done){ C.done=1; G.shake=Math.max(G.shake||0,16); try{ tone('square',70,40,.4,.09); }catch(e){}\n    if(tg&&tg.state!=='ko'&&Math.abs(tg.x-C.hx)<PZSU.rngCam){ hit(f,tg,PZSU.dmgCam,14,44,{sup:true,heavy:true,launch:true,dirx:tg.x>=f.x?1:-1,y:tg.y-160}); if(tg.state==='hit') floatText('CAMPANILE!',tg.x,tg.y-235,'#ffffff',30,60); } }\n  if(C.t>86) f.pcam=null; }\nfunction pazzaMoto(f,o,a,m,fwd){ /*PAZZAMOTO1: lo investe in moto, sul modello della carica a cavallo di Ugo*/\n  if(a.f<m.s){ f.vx=0; return; }\n  if(a.f===m.s){ f.pcar={hit:0,fwd}; G.excite=1; SFX.swing&&SFX.swing(); G.shake=Math.max(G.shake,5); }\n  const Q=f.pcar||(f.pcar={hit:0,fwd});\n  if(Q.hit>0){ Q.hit++; f.vx=fwd*2; return; }\n  f.vx=fwd*PZSU.velM;\n  if(a.f%2===0) for(let k=0;k<2;k++) FX.push({x:f.x-fwd*(50+rnd()*60),y:f.y-6-rnd()*14,vx:-fwd*(1+rnd()*2),vy:-1-rnd()*2,life:18,c:rnd()<.5?'#9a9a9a':'#d8d8d8'});\n  if(o&&!['ko','down'].includes(o.state)){ const dist=(o.x-f.x)*fwd;\n    if(dist>-10&&dist<150&&o.y>f.y-90){ hit(f,o,PZSU.dmgM,14,40,{heavy:true,launch:true,dirx:fwd,y:o.y-130}); Q.hit=1;\n      if(o.state==='hit'){ floatText('ASFALTATO!',o.x,o.y-215,'#ffb347',28,60); G.shake=Math.max(G.shake,12); for(let k=0;k<14;k++) FX.push({x:o.x-fwd*20,y:o.y-130+(rnd()-.5)*40,vx:fwd*(1+rnd()*5)+(rnd()-.5)*4,vy:-1-rnd()*5,life:22,c:k%3===0?'#ffffff':(k%2?'#c8282e':'#1d3c9a')}); } } } }\nfunction pazzaMotoOk(f){ try{ const S=rosaSP(f); return !!(f.def.lv>=2&&S&&S.moto1&&S.moto1.complete&&S.moto1.width); }catch(e){ return false; } }\nfunction drawPazza(F){ if(!F||!F.def||F.def.spriteKey!=='pazza') return; const C=F.pcam; if(!C) return; ctx.save(); ctx.imageSmoothingEnabled=false;\n  const k=C.t; const big=pazzaImg('ovalone'), small=pazzaImg('ovale');\n  if(k<30&&small){ const y=F.y-150-k*k*0.6; const s=0.6; ctx.save(); ctx.translate(F.x+(C.hx-F.x)*(k/30),y); ctx.rotate(k*0.45); ctx.drawImage(small,-small.width*s/2,-small.height*s/2,small.width*s,small.height*s); ctx.restore(); }\n  if(k>=34&&k<58){ const q=(k-34)/24;\n    if(big){ const y=-200+(GROUND-90+200)*q*q; const s=1.0; ctx.save(); ctx.translate(C.hx,y); ctx.rotate(Math.sin(k*0.2)*0.3); ctx.drawImage(big,-big.width*s/2,-big.height*s/2,big.width*s,big.height*s); ctx.restore(); } }\n  else if(k>=58&&k<86&&big){ ctx.globalAlpha=Math.max(0,1-(k-58)/28); const s=1.0; ctx.drawImage(big,C.hx-big.width*s/2,GROUND-big.height*s*0.92,big.width*s,big.height*s); const pv=pazzaImg('polvere'); if(pv){ const z=0.8+(k-58)/28; ctx.drawImage(pv,C.hx-pv.width*z/2,GROUND-pv.height*z*0.8,pv.width*z,pv.height*z); } ctx.globalAlpha=1; }\n  ctx.restore(); }\ntry{ if(typeof ITXY!=='undefined'&&!ITXY['Seregno']) ITXY['Seregno']=[214,256]; }catch(e){}\ntry{ EPICA.pazza=[\"Ex rugbista, prima linea. Chiama SDB \\\"Maestro\\\" e chiude ogni discorso con \\\"coddisse\\\". Placca tutto quello che si muove.\", \"Quando evolve indossa il costume del suo cane e arriva in moto. Quando vince ha una sola parola: CHEGGIOCATORE.\"]; Object.assign(COPPIAT,{\"pazza>stefano\": \"L'allievo contro il Maestro. Pazza Idea si inchina. Poi placca.\", \"stefano>pazza\": \"SDB ha un allievo. L'allievo ha una pazza idea.\", \"pazza>ciuppa\": \"Due rugbisti, una birra in palio. Il terzo tempo si gioca prima.\", \"ciuppa>pazza\": \"Ciuppa conosce i placcaggi di Pazza Idea. Pazza Idea conosce i Dolcetti di Ciuppa.\"}); }catch(e){}\n";